function ProductCard(props) {
    return ( <
        div className = "card" >
        <
        h2 > { props.name } < /h2> <
        p className = "price" > { props.price } < /p>

        <
        p className = { `stock ${props.inStock ? "in" : "out"}` } > { props.inStock ? "In Stock" : "Out of Stock" } <
        /p> <
        /div>
    );
}

export default ProductCard;
